def pimg(f,alt='',cls='',loading='lazy'):
 return f'<img src="assets/{escape(f)}" alt="{escape(alt)}" loading="{loading}" class="{cls}">'

def arrow(icon='arrow'):
 return '<span class="arrow-diagonal" aria-hidden="true">↗</span>' if icon=='up' else '<span aria-hidden="true">↗</span>'

def section_head(index,kicker,title,href=None,text=None):
 return f'<div class="section-head reveal"><div class="section-index"><span>{index}</span><span>{kicker}</span></div><div class="section-head-bottom"><h2>{title}</h2>{f"<a class=\"text-link\" href=\"{href}\">View all <span aria-hidden=\"true\">↗</span></a>" if href else (f"<p>{text}</p>" if text else "")}</div></div>'

def card(pr):
 return f'''<a class="product-card reveal" href="figure-{pr['slug']}.html" data-universe="{pr['universe']}" data-category="{pr['category']}" data-name="{escape(pr['name'].lower())}" aria-label="Discover {escape(pr['name'])}">
 <div class="product-card-media">{pimg(pr['image'],pr['alt'])}<span class="card-corner">{escape(pr['edition'])}</span><span class="round-arrow">↗</span></div>
 <div class="product-card-info"><div><h3>{pr['name']}</h3><p>{pr['sub']}</p></div><span>{pr['universe']} / {pr['category']}</span></div></a>'''

