journal_filters='''<div class="filter-pills journal-pills" role="group" aria-label="Filter editorial posts"><button class="journal-filter active" data-cat="All" aria-pressed="true">All stories</button><button class="journal-filter" data-cat="Events" aria-pressed="false">Events</button><button class="journal-filter" data-cat="Guides" aria-pressed="false">Collector guides</button></div>'''
jcards=''.join(f'''<a href="article-{j['slug']}.html" class="journal-grid-card reveal" data-category="{j['category']}"><div class="journal-grid-media">{pimg(j['image'],j['title'])}<span class="round-arrow">↗</span></div><div class="journal-card-label"><span>{j['label']}</span><span>{j['date']}</span></div><h2>{j['title']}</h2><p>{j['excerpt']}</p><span class="micro">{j['read']}</span></a>''' for j in JOURNAL)
journal_body=intro('04','THE JOURNAL','Culture in <em>focus.</em>','Stories, announcements and perspectives from the intersecting worlds of anime, comics and collecting.')+f'<section class="content-section journal-page">{journal_filters}<div class="journal-grid">{jcards}</div><p class="no-results" id="journal-empty" hidden>No stories in this category.</p></section>'
(ROOT/'journal.html').write_text(shell('Journal','Read convention news, collecting guides and original editorial stories from FRAMEVERSE.',journal_body,page='journal'),encoding='utf-8')

# article pages
for j in JOURNAL:
 if j['category']=='Events':
  details={
   'animejapan-osaka':('The 2027 edition of AnimeJapan marks a move to INTEX Osaka. For visitors, the change means planning around Osaka rather than the Tokyo venue associated with previous editions.','Before arranging travel, use the organizer’s website for admission announcements, access information and any updates to the event programme.'),
   'anime-expo-2027':('Anime Expo will return to the Los Angeles Convention Center from July 2 through July 5, 2027. The convention brings together creators, fans, exhibitors and industry guests.','Ticketing, schedules and entry requirements are managed by the event organizer. Check the official website before making plans.'),
   'comic-con-2027':('San Diego Comic-Con is scheduled for July 22–25, 2027 at the San Diego Convention Center. Preview Night is listed for Wednesday, July 21.','Registration and badge availability are separate from this editorial listing. Refer to Comic-Con International for current information.'),
   'oz-comiccon-2027':('Oz Comic-Con has listed its Melbourne 2027 convention for June 12–13. The programme spans comics, film, gaming, cosplay and broader pop culture.','Venue and access details can change. The official organizer page has the latest visitor information.'),
  }
  paragraphs=details[j['slug']]
 else:
  paragraphs=('A strong collection begins with understanding what each material does well. PVC is often used for dynamic character shapes and a light feel; resin and polystone are associated with detailed, substantial display pieces. A beautiful finish depends as much on sculpt and paint choices as on the base material.','For long-term care, reduce direct UV exposure, keep dust from settling on delicate edges, and avoid heat or humidity extremes. When lighting a display, use gentle indirect illumination rather than placing a hot light source close to the surface.') if j['slug']=='collecting-materials' else ('The most convincing display setups use a clear hierarchy. Start with one hero piece, then let secondary forms and open space guide the eye. A dark background can create depth, but only when the subject is separated through lighting.','Begin with a soft directional light and refine its angle. Avoid exaggerated colored lighting that hides paint detail. Display pieces benefit from a quieter environment and enough breathing room to read as individual objects.')
 related=[x for x in JOURNAL if x['slug']!=j['slug']][:2]
 article=f'''<article class="article-page"><a href="journal.html" class="back-link">← BACK TO JOURNAL</a><div class="article-heading"><span class="micro">{j['label']}</span><h1>{j['title']}</h1><p>{j['excerpt']}</p><div class="article-byline"><span>FRAMEVERSE EDITORIAL</span><span>{j['date']}</span><span>{j['read']}</span></div></div><div class="article-cover">{pimg(j['image'],j['title'],loading='eager')}</div><div class="article-body"><span class="micro">THE STORY</span><p class="article-lead">{paragraphs[0]}</p><p>{paragraphs[1]}</p>{f'<div class="article-source">SOURCE / <a target="_blank" rel="noopener noreferrer" href="{j["source"]}">{j["sourceName"]} ↗</a></div>' if j['source'] else '<div class="article-source">ORIGINAL FRAMEVERSE GUIDE</div>'}<div class="article-nav"><a href="journal.html">← All stories</a><a href="events.html">Upcoming conventions ↗</a></div></div></article><section class="content-section">{section_head('MORE','KEEP READING','More from <em>the journal.</em>','journal.html')}<div class="journal-home-grid">{''.join(f'<a class="journal-home-card" href="article-{x["slug"]}.html"><div>{pimg(x["image"],x["title"])}</div><span class="micro">{x["label"]}</span><h3>{x["title"]}</h3></a>' for x in related)}</div></section>'''
 (ROOT/f'article-{j["slug"]}.html').write_text(shell(j['title'],j['excerpt'],article,page='journal'),encoding='utf-8')

# Craft
craft=intro('05','THE PROCESS','Every surface <em>tells a story.</em>','A closer look at how light, material and presentation shape the experience of collecting.')+'''<section class="craft-hero"><div class="craft-cover">'''+pimg('set4-3.webp','Original collectible statues arranged in a cinematic studio')+'''</div><div class="craft-hero-caption"><span>FORM / MATERIAL / LIGHT</span><span>THE LANGUAGE OF THE OBJECT</span></div></section><section class="content-section craft-text"><div class="craft-chapter reveal"><span class="micro">01 / MATERIAL</span><h2>Built to <em>last.</em></h2><p>From resin and polystone to PVC and mixed media, the visual weight of a figure begins with what it is made of. Scale, surface and silhouette come together to create an unmistakable physical presence.</p></div><div class="craft-chapter reveal"><span class="micro">02 / FINISH</span><h2>Color with <em>intention.</em></h2><p>Subtle transitions, layered paint and the difference between matte and gloss turn a sculpt into an object with personality. Small choices leave the biggest impression.</p></div><div class="craft-chapter reveal"><span class="micro">03 / PRESENTATION</span><h2>Own the <em>frame.</em></h2><p>Display is part of the story. The pedestal, lighting angle and space around an object affect how it is seen. Explore our original image archive through a gallery-first perspective.</p></div></section><section class="content-section craft-next"><div class="craft-next-photo">'''+pimg('set2-3.webp','Gallery display of collectible character concepts')+'''</div><div><span class="micro">COLLECTORS / FIELD NOTES</span><h2>Care beyond the box.</h2><p>Practical guidance for display, lighting, storage and preservation.</p><a href="resources.html" class="pill-cta">Explore resources ↗</a></div></section>'''
(ROOT/'craft.html').write_text(shell('Craft & Materials','Learn about the materials, finishes, lighting and presentation of premium collectibles.',craft,page='craft'),encoding='utf-8')

# Resources
faq=[('Are the featured figures available to buy?','No. The featured FRAMEVERSE character pieces are original visual concepts created for editorial and creative presentation, not commercial inventory.'),('Where can I verify convention dates?','Every event listing includes a link to the official organizer. Always verify dates, venues, ticket availability and entry rules before booking travel.'),('Can I submit an event or suggest a correction?','Yes. Use the contact page with the event name, official source URL and the update you would like us to review.'),('What is the difference between PVC and resin?','PVC is a common, flexible production material for many character figures. Resin and polystone are often used in heavier, highly detailed display statues. Both require sensible handling and storage.'),('How should I clean a collectible?','Start with a soft, dry brush or microfiber cloth. Keep moisture and harsh chemicals away from delicate paints, decals and clear parts; follow product-specific guidance where available.'),('May I reuse FRAMEVERSE images?','The original visual concepts and editorial presentation are not automatically licensed for third-party reuse. Please contact us to discuss a specific request.')]
faqs=''.join(f'<details class="faq-item"><summary><span>{i+1:02d} / {q}</span><span class="faq-plus">+</span></summary><p>{a}</p></details>' for i,(q,a) in enumerate(faq))
resources=intro('06','RESOURCES','Know more. <em>Keep longer.</em>','A practical reference hub for collectors, convention visitors and anyone curious about the craft behind the object.')+f'''<section class="content-section resources-page"><div class="resource-links"><a href="article-collecting-materials.html"><span class="micro">FIELD GUIDE / 001</span><h2>Materials and preservation</h2><span>Read guide ↗</span></a><a href="article-light-and-display.html"><span class="micro">FIELD GUIDE / 002</span><h2>Lighting and display</h2><span>Read guide ↗</span></a><a href="events.html"><span class="micro">DIRECTORY / 003</span><h2>Convention planning</h2><span>Browse events ↗</span></a></div><div class="faq-area"><div><span class="micro">FAQ / QUESTIONS</span><h2>The things<br><em>worth asking.</em></h2><p>Some of the most common questions about our archive and the culture of collecting.</p></div><div class="faq-list">{faqs}</div></div><div class="resource-contact"><h2>Need something <em>else?</em></h2><a class="pill-cta" href="contact.html">Talk to us ↗</a></div></section>'''
(ROOT/'resources.html').write_text(shell('Resources & FAQ','Care guidance, official event verification and frequently asked questions.',resources,page='resources'),encoding='utf-8')

# About
about=intro('07','OUR POINT OF VIEW','For the love of <em>the worlds.</em>','A digital-first destination exploring the objects, artwork and gatherings that connect anime and comics culture.')+'''<section class="about-cover">'''+pimg('set1-3.webp','A gallery display of original collectible figure concepts')+'''<div><span class="micro">BEYOND THE FRAME</span><h2>IT STARTS<br>WITH <em>WONDER.</em></h2></div></section><section class="content-section about-story"><div><span class="micro">WHAT WE BELIEVE</span><h2>Collecting is a way<br>of <em>remembering.</em></h2></div><div><p>FRAMEVERSE is an independent creative platform devoted to anime, comics, figure design and the communities that bring them together.</p><p>We explore these worlds through an original visual concept archive, practical collecting notes and a carefully sourced directory of conventions. Our perspective is editorial and design-led: fewer distractions, more room to see the work.</p><a href="contact.html" class="text-link">Get in touch ↗</a></div></section><section class="about-values content-section"><div><span>01</span><h3>DESIGN FIRST</h3><p>Every composition should earn your attention.</p></div><div><span>02</span><h3>CULTURE IN CONTEXT</h3><p>Respect the creators, communities and source material.</p></div><div><span>03</span><h3>CURIOUS BY NATURE</h3><p>Always exploring what collecting can become.</p></div></section>'''
(ROOT/'about.html').write_text(shell('About','FRAMEVERSE is an independent creative platform exploring anime, comics and the culture of collecting.',about,page='about'),encoding='utf-8')

# Contact
contact=intro('08','CONNECT','The conversation <em>starts here.</em>','Have an event update, a collaboration idea or a question about our creative archive? Reach out.')+'''<section class="contact-page content-section"><div class="contact-note"><span class="micro">FRAMEVERSE / INBOX</span><h2>GOOD IDEAS<br>START WITH<br><em>HELLO.</em></h2><p>Tell us what you have in mind. Completing this form opens your email application with your message pre-filled.</p><a href="mailto:portfolio4684@gmail.com">portfolio4684@gmail.com ↗</a><div class="contact-geometry">✳</div></div><form id="contact-form" class="contact-form"><div class="form-field"><label for="contact-name">01 / YOUR NAME <span>*</span></label><input id="contact-name" name="name" placeholder="What should we call you?" minlength="2" maxlength="80" required></div><div class="form-field"><label for="contact-email">02 / EMAIL ADDRESS <span>*</span></label><input id="contact-email" type="email" name="email" placeholder="Where can we reach you?" required maxlength="160"></div><div class="form-field"><label for="contact-topic">03 / TOPIC <span>*</span></label><select id="contact-topic" name="topic" required><option value="">Select a topic</option><option>Event submission or correction</option><option>Editorial inquiry</option><option>Visual concept inquiry</option><option>Partnership inquiry</option><option>Other</option></select></div><div class="form-field"><label for="contact-message">04 / YOUR MESSAGE <span>*</span></label><textarea id="contact-message" name="message" rows="5" placeholder="Tell us a little more..." minlength="10" maxlength="4000" required></textarea></div><button class="form-submit" type="submit">Continue in email app <span>↗</span></button><p class="form-disclaimer">No data is sent from this webpage. Your email app will open for you to review and send your message.</p></form></section>'''
(ROOT/'contact.html').write_text(shell('Contact','Contact the FRAMEVERSE editorial and creative team.',contact,page='contact'),encoding='utf-8')

privacy=intro('09','PRIVACY','Privacy and <em>clarity.</em>','How this independent website handles visitor information.')+'''<section class="content-section legal"><h2>Our approach</h2><p>FRAMEVERSE does not require you to create an account. This static version does not include advertising trackers, analytics cookies or an on-site user database.</p><h2>Contacting us</h2><p>The contact form opens your email application. Your name, email and message are not transmitted to our servers by the form itself. Sending an email is governed by your email provider and the recipient’s email service.</p><h2>External sites</h2><p>Convention listings link directly to third-party organizers. Their websites operate under their own terms and privacy practices.</p><h2>Updates</h2><p>This policy reflects the initial site release of November 2026 and will be revised if data-processing features are added.</p></section>'''
(ROOT/'privacy.html').write_text(shell('Privacy','How FRAMEVERSE handles visitors’ information.',privacy,page='privacy'),encoding='utf-8')

# data index for global search; only original content published in this project
