for p in PRODUCTS: search_index.append(dict(type='Collection',title=p['name']+' — '+p['sub'],hint=p['universe']+' / '+p['category'],href=f'figure-{p["slug"]}.html'))
for e in EVENTS: search_index.append(dict(type='Event',title=e['title'],hint=e['city']+' · '+e['date'],href=e['link'],external=True))
