 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{site_url}/{p.name}</loc></url>' for p in ROOT.glob('*.html'))+'</urlset>',encoding='utf-8')
